// Shared in-memory store for items. IDs are generated as i1, i2, ... in
// creation order. A Map preserves insertion order so item_list returns items
// in the order they were created.
const store = new Map();
let counter = 0;

function nextId() {
  counter += 1;
  return `i${counter}`;
}

function validateString(value, field) {
  if (typeof value !== 'string') {
    throw new Error(`${field} must be a string`);
  }
}

function ok(payload) {
  return { content: [{ type: 'text', text: JSON.stringify(payload) }] };
}

export async function listTools() {
  return [
    {
      name: 'item_create',
      description: 'Create a new item in the shared in-memory store.',
      inputSchema: {
        type: 'object',
        properties: {
          name: { type: 'string', description: 'Name of the item.' },
          tag: { type: 'string', description: 'Optional tag for the item.' }
        },
        required: ['name'],
        additionalProperties: false
      }
    },
    {
      name: 'item_update',
      description: 'Update an existing item, preserving unspecified fields.',
      inputSchema: {
        type: 'object',
        properties: {
          item_id: { type: 'string', description: 'ID of the item to update.' },
          name: { type: 'string', description: 'New name for the item.' },
          tag: { type: 'string', description: 'New tag for the item.' }
        },
        required: ['item_id'],
        additionalProperties: false
      }
    },
    {
      name: 'item_get',
      description: 'Get a single item by its ID.',
      inputSchema: {
        type: 'object',
        properties: {
          item_id: { type: 'string', description: 'ID of the item to retrieve.' }
        },
        required: ['item_id'],
        additionalProperties: false
      }
    },
    {
      name: 'item_list',
      description: 'List all items in creation order.',
      inputSchema: {
        type: 'object',
        properties: {},
        required: [],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'item_create': {
      validateString(args.name, 'name');
      if (args.tag !== undefined) validateString(args.tag, 'tag');
      const id = nextId();
      const item = { item_id: id, name: args.name };
      if (args.tag !== undefined) item.tag = args.tag;
      store.set(id, item);
      return ok(item);
    }
    case 'item_update': {
      validateString(args.item_id, 'item_id');
      const item = store.get(args.item_id);
      if (!item) throw new Error(`item not found: ${args.item_id}`);
      if (args.name !== undefined) {
        validateString(args.name, 'name');
        item.name = args.name;
      }
      if (args.tag !== undefined) {
        validateString(args.tag, 'tag');
        item.tag = args.tag;
      }
      return ok(item);
    }
    case 'item_get': {
      validateString(args.item_id, 'item_id');
      const item = store.get(args.item_id);
      if (!item) throw new Error(`item not found: ${args.item_id}`);
      return ok(item);
    }
    case 'item_list': {
      return ok([...store.values()]);
    }
    default:
      throw new Error(`unknown tool: ${name}`);
  }
}

